const reviewTaskApproval = `-- name: ReviewTaskApproval :exec
UPDATE task_approvals
SET status = $2, reviewed_by = $3, reviewed_at = now(), review_note = $4
WHERE id = $1 AND status = 'pending'
`

type ReviewTaskApprovalParams struct {
	ID         uuid.UUID  `json:"id"`
	Status     string     `json:"status"`
	ReviewedBy *uuid.UUID `json:"reviewed_by"`
	ReviewNote string     `json:"review_note"`
}

// Only a pending approval can be reviewed; the partial unique index keeps
// one pending row per card, so this is the only open one.
func (q *Queries) ReviewTaskApproval(ctx context.Context, arg ReviewTaskApprovalParams) error {
	_, err := q.db.Exec(ctx, reviewTaskApproval,
		arg.ID,
		arg.Status,
		arg.ReviewedBy,
		arg.ReviewNote,
	)
	return err
}

